parameters.query:
query OrderVariants($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on ProductVariant {
      id
      title
      sku
      inventoryQuantity
      inventoryItem { tracked }
      product {
        title
        roast: metafield(namespace: "coffee", key: "roast") { value }
        brewMethod: metafield(namespace: "coffee", key: "brew_method") { value }
      }
    }
  }
}

